"""Editable document layouts, not color variants. Shared by canvas/PDF/DOCX.

Compatibility labels describe observable layout complexity, not hiring outcomes.
Legacy template identifiers are preserved for existing saved documents.
"""
from typing import Literal

TemplateKey = Literal['classic-ats','traditional-corporate','clean-executive','modern-professional','minimalist','elegant-typography','technical','machine-learning','data-scientist','engineering','student','fresher','internship','experienced','executive-leadership','two-column','sidebar-skills','contemporary-creative']


def layout(name, category, description, **choices):
    value={'name':name,'category':category,'description':description,'font':'sans','body_size':10.5,'heading_size':12,'name_size':27,'leading':15.5,'spacing':7,'margin':43,'accent':'#3448a4','layout':'single','columns':1,'column_ratio':.67,'header':'left','heading':'rule','entries':'plain','skills':'text','bullet':'disc','dividers':True,'rail':[],'lead':[],'levels':['Entry-level','Mid-level','Senior'],'professions':['General professional'],'page_sizes':['A4','LETTER'],'page_hint':'One or two pages','photo_free':True,'compact':False,'focus':'Experience-focused'}
    value.update(choices)
    value['columns']=2 if value['layout'] in ('two-column','sidebar-left','sidebar-right') else 1
    value['ats_oriented']=value['columns']==1 and value['layout']!='labelled'
    value['ats_guidance']='Selectable text with a single content stream and standard headings. Review extraction; no universal ATS guarantee.' if value['ats_oriented'] else 'Selectable text, but columns/sidebars or label rails can change reading order. Review the extracted text before applying.'
    value['docx_guidance']='Word preserves typography, margins, headings, lists and supported column tables. Pagination may differ from PDF; custom browser details are approximated.'
    return value


